// ConfirmKeyResult The code was correct. The key is in the body, for the only time.
//
// Example: {"apiKey":"qk_live_EXAMPLEONLYnotarealkey","replaced":false}
type ConfirmKeyResult struct {
	// ApiKey The API key, in full, the only time it is ever shown. It is stored as a SHA-256 hash, so it cannot be recovered or displayed again — store it before you discard the response.
	ApiKey string `json:"apiKey"`

	// Replaced Whether this address already had a key. `true` means the previous one stopped working the moment this one was issued, so anything still using it now gets a 401. `false` is a first-time signup.
	Replaced bool `json:"replaced"`
}

// ErrorCode Machine-readable failure code. Stable across releases, so this is the field to branch on. `message` is not stable — it is written for a human reading a log and may be reworded at any time.
type ErrorCode string

// ErrorResponse defines model for ErrorResponse.
type ErrorResponse struct {
	Error struct {
		// Code Machine-readable failure code. Stable across releases, so this is the field to branch on. `message` is not stable — it is written for a human reading a log and may be reworded at any time.
		Code ErrorCode `json:"code"`

		// Message What went wrong, in English, for a human to read. Do not match on it — see `code`.
		Message string `json:"message"`
	} `json:"error"`
}

// QrDesignConfig The full design — module and finder styles, colors, logo and halo. The [QR Designer](https://qrocodile.io/en/) produces exactly this object: build the QR code there, open the encoded-content bar with the chevron at the bottom right of the preview, then choose “Copy JSON” and paste the result here. Every ID and style parameter is also tabulated on the [API page](https://qrocodile.io/en/qr-code-api/). One exception: an animated design also carries an `animation` field, which this endpoint rejects because it renders a single image — remove that field to render a still.
type QrDesignConfig struct {
	// Background Background color, or `transparent` to leave it unpainted.
	Background *QrDesignConfig_Background `json:"background,omitempty"`

	// ErrorCorrection Error correction level. Omit to auto-resolve from the logo/style — set this only when a design has a fixed level rather than an auto-resolved one, e.g. a content type whose standard mandates it (L 7%, M 15%, Q 25%, H 30% redundancy).
	ErrorCorrection *QrDesignConfigErrorCorrection `json:"errorCorrection,omitempty"`

	// FinderColorInherit Corners take their per-cell color from the pattern instead of `finderFrameColor` and `finderEyeColor`.
	FinderColorInherit *bool `json:"finderColorInherit,omitempty"`

	// FinderEyeColor Color of the inner eye of each corner finder.
	FinderEyeColor *QrDesignConfig_FinderEyeColor `json:"finderEyeColor,omitempty"`

	// FinderFrameColor Color of the outer frame of each corner finder.
	FinderFrameColor *QrDesignConfig_FinderFrameColor `json:"finderFrameColor,omitempty"`

	// FinderStyleId Shape the three corner finders are drawn with.
	FinderStyleId *QrDesignConfigFinderStyleId `json:"finderStyleId,omitempty"`

	// FinderStyleParams Tuning parameters for the finder style. Which keys it accepts depends on the style: the [QR Designer](https://qrocodile.io/en/) exposes them as that style’s own sliders, and they are tabulated per style on the [API page](https://qrocodile.io/en/qr-code-api/). An unrecognized key is ignored rather than rejected — a style that drops a parameter should not break a stored design — though a key over 64 characters is refused.
	FinderStyleParams *map[string]QrDesignConfig_FinderStyleParams_AdditionalProperties `json:"finderStyleParams,omitempty"`

	// FinderUseModuleStyle Let the module style draw the corner finders itself. Only effective for styles that can render finders, and the only way to express relief and 3D designs whose corners must stay depth-sorted with the pattern. Supersedes `finderStyleId`.
	FinderUseModuleStyle *bool `json:"finderUseModuleStyle,omitempty"`

	// Halo Decoration scattered around the QR code, drawn with the design’s own module style.
	Halo *struct {
		// Cluster How much the halo modules clump together: 0 scatters them at random, 1 gathers them into smooth clumps.
		Cluster *float32 `json:"cluster,omitempty"`

		// Color Where the halo takes its colors from.
		Color *struct {
			// Fade How far the outermost halo modules fade toward the background. 0 is no fade.
			Fade *float32 `json:"fade,omitempty"`

			// Mode Where the halo takes its colors from: `inherit` reuses the code’s own pattern colors, `palette` uses the `palette` below.
			Mode *QrDesignConfigHaloColorMode `json:"mode,omitempty"`

			// Palette Colors the halo is drawn from when `mode` is `palette`.
			Palette *[]string `json:"palette,omitempty"`

			// PaletteMode How the halo’s palette colors are distributed. Defaults to the code’s own `paletteMode`, or `scatter` when that is unset too.
			PaletteMode *QrDesignConfigHaloColorPaletteMode `json:"paletteMode,omitempty"`
		} `json:"color,omitempty"`

		// Curve How quickly the halo thins out with distance from the code.
		Curve *QrDesignConfigHaloCurve `json:"curve,omitempty"`

		// Density Peak fraction of cells filled, measured nearest the code.
		Density *float32 `json:"density,omitempty"`

		// Enabled Draw the halo. Sending a `halo` object at all switches it on, so this need only be set to turn one off: `false` keeps the settings below while suppressing the decoration. Omit the whole `halo` object for a design that has none.
		Enabled *bool `json:"enabled,omitempty"`

		// Falloff Shape the halo fades along — square, soft square, or round.
		Falloff *QrDesignConfigHaloFalloff `json:"falloff,omitempty"`

		// Margin Plain background kept outside the halo, in modules.
		Margin *float32 `json:"margin,omitempty"`

		// Mode How the halo and the QR code are drawn together. `composite` (layered) leaves the code exactly as it looks without a halo. `unified` (integrated) merges both into one drawing, so 3D styles cast shadows across the halo — at the cost of the code itself looking slightly different.
		Mode *QrDesignConfigHaloMode `json:"mode,omitempty"`

		// QuietZone The total light ring the viewer sees between the pattern and the halo, in modules. The code’s own `margin` counts toward it rather than adding to it, so a value at or below `margin` leaves no gap at all — with the default margin of 2, the halo starts right at the code until this reaches 3.
		QuietZone *float32 `json:"quietZone,omitempty"`

		// Seed Scatter seed. The same seed redraws the same halo, so a render is reproducible; change it for a different arrangement of the same settings.
		Seed *int `json:"seed,omitempty"`

		// Spread How far the halo reaches beyond the quiet zone, in modules. One module is the minimum, so 0 renders as 1.
		Spread *float32 `json:"spread,omitempty"`
	} `json:"halo,omitempty"`

	// Logo A logo placed on the QR code: either a built-in icon by `id`, or your own artwork as base64 in `data`. Not both.
	Logo *QrDesignConfig_Logo `json:"logo,omitempty"`

	// Margin Quiet zone around the QR code, in modules. One module is the minimum, so 0 and 1 both render a single-module zone.
	Margin *int `json:"margin,omitempty"`

	// ModuleColor Color of the modules — a solid hex color or a gradient.
	ModuleColor *QrDesignConfig_ModuleColor `json:"moduleColor,omitempty"`

	// ModulePalette Draw the modules from several colors at once, arranged by `paletteMode`. Use this instead of `moduleColor` for multi-color patterns.
	ModulePalette *[]string `json:"modulePalette,omitempty"`

	// ModuleStyleId Shape the modules (the pattern) are drawn with. The enum lists every style this build can render.
	ModuleStyleId *QrDesignConfigModuleStyleId `json:"moduleStyleId,omitempty"`

	// ModuleStyleParams Tuning parameters for the module style. Which keys it accepts depends on the style: the [QR Designer](https://qrocodile.io/en/) exposes them as that style’s own sliders, and they are tabulated per style on the [API page](https://qrocodile.io/en/qr-code-api/). An unrecognized key is ignored rather than rejected — a style that drops a parameter should not break a stored design — though a key over 64 characters is refused.
	ModuleStyleParams *map[string]QrDesignConfig_ModuleStyleParams_AdditionalProperties `json:"moduleStyleParams,omitempty"`

	// PaletteDither Jitter of the color-sample position, in modules, which breaks hard palette bands into a grain, off at 0.
	PaletteDither *float32 `json:"paletteDither,omitempty"`

	// PaletteMode How the palette colors are distributed across the modules.
	PaletteMode *QrDesignConfigPaletteMode `json:"paletteMode,omitempty"`

	// PaletteScale Scale of the pattern that `paletteMode` lays over the modules.
	PaletteScale *float32 `json:"paletteScale,omitempty"`

	// Preset A built-in preset loaded as the starting point. Fields set alongside it override the preset’s own values, so a preset plus `moduleColor` is a recolored preset.
	Preset *QrDesignConfigPreset `json:"preset,omitempty"`
}

